// Writes supabase/seed.sql from the same definitions the app uses, so they never drift apart.
// Run: npm run seed:sql
import { writeFileSync } from 'node:fs';
import { METRIC_LIBRARY } from '../src/lib/ekoa';
import { CIRCLES, POLICY_CLAUSES } from '../src/lib/clauses';

const q = (v: unknown) => (v === null || v === undefined ? 'null' : typeof v === 'boolean' || typeof v === 'number' ? String(v) : `'${String(v).replace(/'/g, "''")}'`);
const j = (v: unknown) => `'${JSON.stringify(v).replace(/'/g, "''")}'::jsonb`;

const lines: string[] = [
  '-- Generated by scripts/generate-seed-sql.ts. Starting content for a new Ekoa database.',
  '-- Safe to re-run: existing rows are updated, not duplicated.',
  '',
  '-- Metric library',
];
for (const m of METRIC_LIBRARY) {
  lines.push(
    `insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values (${[m.code, m.name, m.unit, m.category, m.protocol, m.frequency, m.comparability_notes].map(q).join(', ')}, ${m.higher_is_better}, ${m.is_impact}, ${j(m.inputs)}, ${m.version})`,
    `  on conflict (code) do update set name = excluded.name, unit = excluded.unit, protocol = excluded.protocol, frequency = excluded.frequency, comparability_notes = excluded.comparability_notes, inputs = excluded.inputs;`,
  );
}
lines.push('', '-- Circles');
for (const [name, theme, d] of CIRCLES) lines.push(`insert into public.circles (name, theme, description) values (${q(name)}, ${q(theme)}, ${q(d)}) on conflict (theme) do nothing;`);
lines.push('', '-- Policy clause library (from the first collaborating school’s policy)');
for (const [section, title, body] of POLICY_CLAUSES) {
  lines.push(`insert into public.policy_clauses (section, title, body, adoption_count) select ${q(section)}, ${q(title)}, ${q(body)}, 0 where not exists (select 1 from public.policy_clauses where title = ${q(title)});`);
}
lines.push(
  '',
  '-- First cohort',
  "insert into public.cohorts (name, starts_on) select 'Founding Cohort', current_date where not exists (select 1 from public.cohorts where name = 'Founding Cohort');",
  '',
  '-- The Ekoa steward organisation. Add the first stewards with supabase/bootstrap-steward.sql.',
  "insert into public.organisations (name, org_type, country, city, status) select 'Ekoa Stewards', 'ekoa', 'India', 'Faridabad', 'active' where not exists (select 1 from public.organisations where org_type = 'ekoa');",
  '',
  '-- The two Ekoa audit schools, which carry out T3 peer audits. Both have confirmed.',
  "insert into public.organisations (name, org_type, country, city, status, public_visible, audit_school) select 'Shiv Nadar School, Faridabad', 'school', 'India', 'Faridabad', 'active', true, true where not exists (select 1 from public.organisations where name = 'Shiv Nadar School, Faridabad');",
  "insert into public.organisations (name, org_type, country, city, status, public_visible, audit_school) select 'Green School, Bali', 'school', 'Indonesia', 'Badung, Bali', 'active', true, true where not exists (select 1 from public.organisations where name = 'Green School, Bali');",
  '',
);
writeFileSync('supabase/seed.sql', lines.join('\n'));
console.log(`Wrote supabase/seed.sql: ${METRIC_LIBRARY.length} metrics, ${CIRCLES.length} circles, ${POLICY_CLAUSES.length} clauses.`);
